import fs from "node:fs";

const details = JSON.parse(fs.readFileSync("reports/Invoicing-MService/2026-10-28/open-story-details.out.json", "utf8"));
const byId = new Map();
for (const call of details) {
  const item = call?.data?.items?.[0];
  if (item) byId.set(item.itemId, item);
}

const AR = (s) => `<p dir="rtl">${s}</p>`;
const EN = (s) => `<p dir="ltr">${s}</p>`;
const H = (n, ar, en) => `<h3>${n}. ${ar} | ${en}</h3>`;
const AC = (items) => `<ol>${items.map(([a, e]) => `<li><strong>AR:</strong> ${a}<br/><strong>EN:</strong> ${e}</li>`).join("")}</ol>`;
const UL = (items) => `<ul>${items.map((x) => `<li>${x}</li>`).join("")}</ul>`;

function doc({ arTitle, enTitle, summaryAr, summaryEn, userAr, userEn, ac, funcAr, funcEn, techAr, techEn, outAr, outEn, depsAr, depsEn, dorAr, dorEn, estAr, estEn }) {
  return [
    `<h2>${arTitle} | ${enTitle}</h2>`,
    H(1, "ملخص القصة", "Story Summary"), AR(summaryAr), EN(summaryEn),
    H(2, "المستخدم والقيمة", "User & Value"), AR(userAr), EN(userEn),
    H(3, "معايير القبول", "Acceptance Criteria"), AC(ac),
    H(4, "التفاصيل الوظيفية", "Functional Details"), AR(funcAr), EN(funcEn),
    H(5, "التفاصيل التقنية", "Technical Notes"), AR(techAr), EN(techEn),
    H(6, "خارج النطاق", "Out of Scope"), AR(outAr), EN(outEn),
    H(7, "التبعيات والروابط", "Dependencies & Links"), AR(depsAr), EN(depsEn),
    H(8, "الجاهزية والاكتمال", "Definition of Ready & Done"), AR(dorAr), EN(dorEn),
    H(9, "التقدير والأولوية", "Estimation & Priority"), AR(estAr), EN(estEn),
  ].join("\n");
}

