const SEP = `<p dir="ltr"><strong>##+=================================================##</strong></p>`;
const calls = [];
for (const [itemId, cfg] of Object.entries(content)) {
  const item = byId.get(itemId);
  if (!item) throw new Error(`Missing detail for ${itemId}`);
  const old = item.description || "";
  const description = old.trim()
    ? `${old}\n${SEP}\n${cfg.html}`
    : cfg.html;
  calls.push({
    tool: "ZohoSprints_UpdateItem",
    args: {
      headers: { "x-za-ui-version": "v2", "X-convert-response": "true" },
      path_variables: {
        teamId: "767679505",
        projectId: "120216000000593007",
        sprintId: cfg.sprintId,
        itemId,
      },
      query_params: { description },
    },
  });
  console.log(item.itemNo, itemId, "old", old.length, "new", description.length);
}
fs.writeFileSync("reports/Invoicing-MService/2026-10-28/description-updates.json", JSON.stringify(calls, null, 2), "utf8");
console.log("calls", calls.length);
